default.shell:
$mismatchCount = 0

$key = Get-Item -LiteralPath 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\System' -ErrorAction SilentlyContinue
$current = $null
if ($key) { $current = $key.GetValue('LocalAccountTokenFilterPolicy', $null, 'DoNotExpandEnvironmentNames') }
if (-not ($current -is [int] -and [BitConverter]::ToUInt32([BitConverter]::GetBytes($current), 0) -eq [uint32]0)) {
    Write-Output 'Mismatch: HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\System [LocalAccountTokenFilterPolicy]'
    $mismatchCount++
}

if ($mismatchCount -gt 0) { exit 1 }
exit 0

---

{{ if and (ne .Vars.win25cis_system_role "domaincontroller") .Vars.win25cis_level_1 }}
  {{ if .Vars.win25cis_rule_18_4_1 }}
    {{ if ne .Vars.win25cis_system_role "domaincontroller" }}
registry:
  HKLM\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\System\LocalAccountTokenFilterPolicy:
    title: "18.4.1 | Ensure 'Apply UAC restrictions to local accounts on network logons' is set to 'Enabled' (MS only) | LocalAccountTokenFilterPolicy"
    exists: true
    value: 0
    type: REG_DWORD
    meta:
      memberserver: 1
      server: 1
      CIS_ID:
        - 18.4.1
      NIST800-53R5:
        - AC-2(9)
    {{ end }}
  {{ end }}
{{ end }}

steps.shell:
$ErrorActionPreference = 'Stop'
trap { Write-Output $_.Exception.Message; exit 1 }

if (-not (Test-Path -LiteralPath 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\System')) {
    New-Item -Path 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\System' -Force | Out-Null
}
New-ItemProperty -LiteralPath 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\System' -Name 'LocalAccountTokenFilterPolicy' -Value 0 -PropertyType DWord -Force | Out-Null
exit 0
